// Student Recent Lessons & Analytics Interfaces & Helper Data Generator
export interface StudentLessonRecord {
  id: string;
  lessonTitle: string;
  unitTitle: string;
  grade: string;
  category: 'vocab' | 'listening' | 'speaking' | 'reading' | 'grammar' | 'exam';
  categoryLabel: string;
  score: number;
  maxScore: number;
  accuracyPercent: number;
  starsEarned: number;
  xpEarned: number;
  durationSeconds: number;
  completedAt: string;
  completedAtMs: number;
  status: 'passed' | 'perfect' | 'in_progress';
}

export interface DailyStudyMetric {
  dayLabel: string;
  dateStr: string;
  studyMinutes: number;
  completedCount: number;
  avgAccuracy: number;
}

export function removeVietnameseTones(str: string): string {
  if (!str) return '';
  return str
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .toLowerCase();
}

export function computeAccountsDiff(prevAccs: UserAccount[], nextAccs: UserAccount[]): string {
  if (!prevAccs || !nextAccs) return 'Không có thông tin';

  const prevMap = new Map(prevAccs.map((a) => [a.id, a]));
  const nextMap = new Map(nextAccs.map((a) => [a.id, a]));

  const modified: string[] = [];
  const added: string[] = [];
  const deleted: string[] = [];

  for (const prev of prevAccs) {
    const next = nextMap.get(prev.id);
    const roleTag = prev.role === 'admin' ? '👑 Admin' : prev.role === 'parent' ? '👨‍👩‍👧 Phụ huynh' : '🧒 Học sinh';

    if (!next) {
      deleted.push(`❌ ${prev.name} (@${prev.username || prev.id}, ${roleTag}) [Đã xóa]`);
    } else {
      const changes: string[] = [];
      if ((prev.level ?? 0) !== (next.level ?? 0)) changes.push(`Level: Lv.${prev.level ?? 0} ➔ Lv.${next.level ?? 0}`);
      if ((prev.stars ?? 0) !== (next.stars ?? 0)) changes.push(`Sao: ⭐${prev.stars ?? 0} ➔ ⭐${next.stars ?? 0}`);
      if ((prev.xp ?? 0) !== (next.xp ?? 0)) changes.push(`XP: ${prev.xp ?? 0} ➔ ${next.xp ?? 0}`);
      if ((prev.streakDays ?? 0) !== (next.streakDays ?? 0)) changes.push(`Streak: 🔥${prev.streakDays ?? 0}d ➔ 🔥${next.streakDays ?? 0}d`);
      if (!!prev.checkedInToday !== !!next.checkedInToday) {
        changes.push(`Điểm danh: ${prev.checkedInToday ? 'Đã điểm danh' : 'Chưa điểm danh'} ➔ ${next.checkedInToday ? 'Đã điểm danh' : 'Chưa điểm danh'}`);
      }
      if (prev.isVip !== next.isVip || prev.vipExpiryDate !== next.vipExpiryDate) {
        const prevStr = prev.isVip ? `VIP (${prev.vipExpiryDate || 'PRO'})` : 'Miễn phí';
        const nextStr = next.isVip ? `VIP (${next.vipExpiryDate || 'PRO'})` : 'Miễn phí';
        changes.push(`Gói VIP: ${prevStr} ➔ ${nextStr}`);
      }
      if ((prev.trialTimeSeconds ?? 0) !== (next.trialTimeSeconds ?? 0)) {
        changes.push(`Thử nghiệm: ${Math.ceil((prev.trialTimeSeconds ?? 0) / 86400)}d ➔ ${Math.ceil((next.trialTimeSeconds ?? 0) / 86400)}d`);
      }
      if (prev.isDeleted !== next.isDeleted) {
        changes.push(next.isDeleted ? 'Thùng rác: Không ➔ Có' : 'Khôi phục: Có ➔ Không');
      }
      if (JSON.stringify(prev.allowedGrades || []) !== JSON.stringify(next.allowedGrades || [])) {
        changes.push('Đổi phân quyền lớp học');
      }
      if (prev.name !== next.name) changes.push(`Tên: ${prev.name} ➔ ${next.name}`);
      if (prev.username !== next.username) changes.push(`Username: @${prev.username} ➔ @${next.username}`);

      if (changes.length > 0) {
        modified.push(`👤 ${prev.name} (${roleTag}): [${changes.join(', ')}]`);
      }
    }
  }

  for (const next of nextAccs) {
    if (!prevMap.has(next.id)) {
      const roleTag = next.role === 'admin' ? '👑 Admin' : next.role === 'parent' ? '👨‍👩‍👧 Phụ huynh' : '🧒 Học sinh';
      added.push(`➕ ${next.name} (@${next.username || next.id}, ${roleTag}) [Tạo mới]`);
    }
  }

  const parts: string[] = [];
  if (modified.length > 0) parts.push(`Cập nhật (${modified.length} TK): ${modified.join(' | ')}`);
  if (added.length > 0) parts.push(`Tạo mới (${added.length} TK): ${added.join(', ')}`);
  if (deleted.length > 0) parts.push(`Xóa (${deleted.length} TK): ${deleted.join(', ')}`);

  return parts.length > 0 ? parts.join(' || ') : 'Trùng khớp - Không có thay đổi chỉ số';
}

export interface DiffChunk {
  type: 'same' | 'added' | 'removed';
  value: string;
}

export function computeWordAndCharDiff(oldStr: string = '', newStr: string = ''): {
  oldChunks: DiffChunk[];
  newChunks: DiffChunk[];
} {
  if (!oldStr && !newStr) return { oldChunks: [], newChunks: [] };
  if (!oldStr) {
    return {
      oldChunks: [],
      newChunks: [{ type: 'added', value: newStr }],
    };
  }
  if (!newStr) {
    return {
      oldChunks: [{ type: 'removed', value: oldStr }],
      newChunks: [],
    };
  }
  if (oldStr === newStr) {
    return {
      oldChunks: [{ type: 'same', value: oldStr }],
      newChunks: [{ type: 'same', value: newStr }],
    };
  }

  const tokenize = (s: string) =>
    s.match(/[\wàáảãạăằắẳẵặâầấẩẫậèéẻẽẹêềếểễệìíỉĩịòóỏõọôồốổỗộơờớởỡợùúủũụưừứửữựỳýỷỹỵđ]+|[^\w\s]+|\s+/gi) || [s];

  const oldTokens = tokenize(oldStr);
  const newTokens = tokenize(newStr);

  const m = oldTokens.length;
  const n = newTokens.length;
  const dp: number[][] = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (oldTokens[i - 1] === newTokens[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }

  let i = m;
  let j = n;
  const oldResult: DiffChunk[] = [];
  const newResult: DiffChunk[] = [];

  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && oldTokens[i - 1] === newTokens[j - 1]) {
      oldResult.unshift({ type: 'same', value: oldTokens[i - 1] });
      newResult.unshift({ type: 'same', value: newTokens[j - 1] });
      i--;
      j--;
    } else if (j > 0 && (i === 0 || dp[i][j - 1] >= dp[i - 1][j])) {
      newResult.unshift({ type: 'added', value: newTokens[j - 1] });
      j--;
    } else if (i > 0 && (j === 0 || dp[i][j - 1] < dp[i - 1][j])) {
      oldResult.unshift({ type: 'removed', value: oldTokens[i - 1] });
      i--;
    }
  }

  return { oldChunks: oldResult, newChunks: newResult };
}

export function SideBySideDiffView({ oldValue = '', newValue = '' }: { oldValue?: string; newValue?: string }) {
  const { oldChunks, newChunks } = computeWordAndCharDiff(oldValue || 'Chưa có thông tin cũ', newValue || 'Đã cập nhật');

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs font-mono my-1.5">
      {/* Old Value Side */}
      <div className="p-2.5 rounded-xl bg-rose-50/90 border border-rose-200/90 space-y-1">
        <div className="flex items-center justify-between text-[10px] font-black text-rose-800 uppercase tracking-wider border-b border-rose-200/70 pb-1">
          <span>🔴 Giá trị cũ (Old)</span>
          <span className="text-[9px] bg-rose-200/80 text-rose-900 px-1.5 py-0.2 rounded font-bold">Xóa / Cũ</span>
        </div>
        <div className="leading-relaxed break-words pt-1 font-medium text-slate-800">
          {oldChunks.length > 0 ? (
            oldChunks.map((chunk, idx) => (
              <span
                key={idx}
                className={
                  chunk.type === 'removed'
                    ? 'bg-rose-200/90 text-rose-950 font-black line-through px-1 py-0.5 rounded shadow-2xs border border-rose-300 mx-0.5 inline-block'
                    : 'text-slate-700'
                }
              >
                {chunk.value}
              </span>
            ))
          ) : (
            <span className="text-slate-400 italic">Không có dữ liệu</span>
          )}
        </div>
      </div>

      {/* New Value Side */}
      <div className="p-2.5 rounded-xl bg-emerald-50/90 border border-emerald-200/90 space-y-1">
        <div className="flex items-center justify-between text-[10px] font-black text-emerald-800 uppercase tracking-wider border-b border-emerald-200/70 pb-1">
          <span>🟢 Giá trị mới (New)</span>
          <span className="text-[9px] bg-emerald-200/80 text-emerald-900 px-1.5 py-0.2 rounded font-bold">Thêm / Mới</span>
        </div>
        <div className="leading-relaxed break-words pt-1 font-medium text-slate-800">
          {newChunks.length > 0 ? (
            newChunks.map((chunk, idx) => (
              <span
                key={idx}
                className={
                  chunk.type === 'added'
                    ? 'bg-emerald-200/90 text-emerald-950 font-black px-1 py-0.5 rounded shadow-2xs border border-emerald-300 mx-0.5 inline-block'
                    : 'text-slate-700'
                }
              >
                {chunk.value}
              </span>
            ))
          ) : (
            <span className="text-slate-400 italic">Không có dữ liệu</span>
          )}
        </div>
      </div>
    </div>
  );
}

export function getStudentLessonData(acc: UserAccount) {
  const storageKey = `DINO_LESSONS_HISTORY_${acc.id}`;
  let customLessons: StudentLessonRecord[] = [];
  try {
    const raw = localStorage.getItem(storageKey);
    if (raw) customLessons = JSON.parse(raw);
  } catch {}

  const gradeStr = acc.allowedGrades && acc.allowedGrades.length > 0 && !acc.allowedGrades.includes('all')
    ? `Lớp ${acc.allowedGrades[0].replace('grade-', '')}`
    : 'Lớp 3';

  const topics = [
    { title: 'Unit 1: All about me! - Bài 1: Từ vựng bản thân & sở thích', category: 'vocab', categoryLabel: 'Từ vựng & Mẫu câu', grade: gradeStr },
    { title: 'Unit 1: All about me! - Bài 2: Phát âm & Hội thoại giao tiếp', category: 'speaking', categoryLabel: 'Luyện Nghe - Nói', grade: gradeStr },
    { title: 'Unit 2: Our homes - Bài 1: Nơi ở & Địa chỉ gia đình', category: 'vocab', categoryLabel: 'Từ vựng & Mẫu câu', grade: gradeStr },
    { title: 'Unit 2: Our homes - Bài 3: Đọc hiểu ngôi nhà mơ ước', category: 'reading', categoryLabel: 'Đọc & Viết', grade: gradeStr },
    { title: 'Luyện nghe phản xạ Shadowing: My Favorite Pet', category: 'listening', categoryLabel: 'Luyện Nghe - Nói', grade: gradeStr },
    { title: 'Ngữ pháp Tương lai đơn: Will & Be going to', category: 'grammar', categoryLabel: 'Ngữ pháp', grade: gradeStr },
    { title: 'Bài kiểm tra thử Học Kỳ 1 - Tiếng Anh ' + gradeStr, category: 'exam', categoryLabel: 'Bài Kiểm Tra', grade: gradeStr },
    { title: 'Flashcards 50 Từ vựng chủ đề Động vật & Thiên nhiên', category: 'vocab', categoryLabel: 'Từ vựng & Mẫu câu', grade: gradeStr },
    { title: 'Unit 3: My foreign friends - Bài 2: Quốc tịch & Tính cách', category: 'vocab', categoryLabel: 'Từ vựng & Mẫu câu', grade: gradeStr },
    { title: 'Luyện phát âm AI: 20 Câu giao tiếp thường gặp hàng ngày', category: 'speaking', categoryLabel: 'Luyện Nghe - Nói', grade: gradeStr },
    { title: 'Bài tập trắc nghiệm Động từ Bất quy tắc thông dụng', category: 'grammar', categoryLabel: 'Ngữ pháp', grade: gradeStr },
    { title: 'Đọc hiểu đoạn văn ngắn: A Day at the Zoo', category: 'reading', categoryLabel: 'Đọc & Viết', grade: gradeStr },
    { title: 'Unit 4: Our free time activities - Bài 1: Hoạt động rảnh rỗi', category: 'vocab', categoryLabel: 'Từ vựng & Mẫu câu', grade: gradeStr },
    { title: 'Kiểm tra 15 phút: Ôn tập Từ vựng Unit 1 - 3', category: 'exam', categoryLabel: 'Bài Kiểm Tra', grade: gradeStr },
  ];

  const now = Date.now();
  const dayMs = 86400000;

  const generatedLessons: StudentLessonRecord[] = topics.map((t, idx) => {
    const timeOffset = idx * (dayMs * 0.45) + (idx % 3) * 3600000;
    const itemTime = now - timeOffset;
    const score = 80 + ((idx * 7 + (acc.stars || 10)) % 21); // 80 - 100
    const isPerfect = score === 100;
    const dateObj = new Date(itemTime);

    let timeLabel = '';
    const diffHours = (now - itemTime) / 3600000;
    if (diffHours < 2) {
      timeLabel = `${Math.max(5, Math.floor(diffHours * 60))} phút trước`;
    } else if (diffHours < 24) {
      timeLabel = `Hôm nay ${dateObj.getHours().toString().padStart(2, '0')}:${dateObj.getMinutes().toString().padStart(2, '0')}`;
    } else if (diffHours < 48) {
      timeLabel = `Hôm qua ${dateObj.getHours().toString().padStart(2, '0')}:${dateObj.getMinutes().toString().padStart(2, '0')}`;
    } else {
      timeLabel = `${dateObj.getDate().toString().padStart(2, '0')}/${(dateObj.getMonth() + 1).toString().padStart(2, '0')}/${dateObj.getFullYear()}`;
    }

    return {
      id: `les-${acc.id}-${idx}`,
      lessonTitle: t.title,
      unitTitle: t.title.split(' - ')[0],
      grade: t.grade,
      category: t.category as any,
      categoryLabel: t.categoryLabel,
      score,
      maxScore: 100,
      accuracyPercent: score,
      starsEarned: isPerfect ? 20 : 10 + (score >= 90 ? 5 : 0),
      xpEarned: score * 2,
      durationSeconds: 180 + ((idx * 35) % 300),
      completedAt: timeLabel,
      completedAtMs: itemTime,
      status: isPerfect ? 'perfect' : 'passed',
    };
  });

  const dayNames = ['CN', 'T2', 'T3', 'T4', 'T5', 'T6', 'T7'];
  const dailyMetrics: DailyStudyMetric[] = [];

  for (let i = 6; i >= 0; i--) {
    const d = new Date(now - i * dayMs);
    const dayLabel = dayNames[d.getDay()];
    const dateStr = `${d.getDate().toString().padStart(2, '0')}/${(d.getMonth() + 1).toString().padStart(2, '0')}`;
    const studyMinutes = 15 + ((i * 11 + (acc.level || 1) * 5) % 35);
    const completedCount = Math.max(1, Math.floor(studyMinutes / 10));
    const avgAccuracy = 85 + ((i * 3 + (acc.stars || 5)) % 16);

    dailyMetrics.push({
      dayLabel,
      dateStr,
      studyMinutes,
      completedCount,
      avgAccuracy,
    });
  }

  const allLessons = customLessons.length > 0 ? customLessons : generatedLessons;

  const totalLessons = acc.completedLessons && acc.completedLessons > 0 ? acc.completedLessons : allLessons.length;
  const totalMinutes = acc.studyTimeMinutes && acc.studyTimeMinutes > 0 ? acc.studyTimeMinutes : dailyMetrics.reduce((sum, d) => sum + d.studyMinutes, 0) * 3;
  const avgAccuracy = Math.round(allLessons.reduce((sum, l) => sum + l.accuracyPercent, 0) / (allLessons.length || 1));
  const perfectCount = allLessons.filter(l => l.status === 'perfect' || l.accuracyPercent === 100).length;
  const totalStarsEarned = allLessons.reduce((sum, l) => sum + l.starsEarned, 0);

  return {
    lessons: allLessons,
    dailyMetrics,
    summary: {
      totalLessons,
      totalMinutes,
      avgAccuracy,
      perfectCount,
      totalStarsEarned,
    },
  };
};

// Helper component to highlight matching search text in account names & usernames
interface HighlightTextProps {
  text: string;
  query: string;
  className?: string;
  highlightClassName?: string;
}

const HighlightText: React.FC<HighlightTextProps> = ({
  text,
  query,
  className = '',
  highlightClassName = 'bg-amber-300 text-amber-950 font-black px-1 rounded-xs shadow-2xs mx-[0.5px] inline-block leading-snug',
}) => {
  if (!query || !query.trim() || !text) {
    return <span className={className}>{text}</span>;
  }

  let rawQuery = query.trim();
  if (rawQuery.startsWith('@') && rawQuery.length > 1 && !text.startsWith('@')) {
    rawQuery = rawQuery.substring(1);
  }

  const normalizedQuery = removeVietnameseTones(rawQuery);
  const normalizedText = removeVietnameseTones(text);

  if (!normalizedQuery || !normalizedText.includes(normalizedQuery)) {
    return <span className={className}>{text}</span>;
  }

  const matchRanges: [number, number][] = [];
  let startIndex = 0;
  while (startIndex < normalizedText.length) {
    const foundIndex = normalizedText.indexOf(normalizedQuery, startIndex);
    if (foundIndex === -1) break;
    matchRanges.push([foundIndex, foundIndex + normalizedQuery.length]);
    startIndex = foundIndex + Math.max(1, normalizedQuery.length);
  }

  if (matchRanges.length === 0) {
    return <span className={className}>{text}</span>;
  }

  const elements: React.ReactNode[] = [];
  let lastEnd = 0;

  matchRanges.forEach(([start, end], i) => {
    if (start > lastEnd) {
      elements.push(text.substring(lastEnd, start));
    }
    elements.push(
      <mark key={`hl-${i}`} className={highlightClassName}>
        {text.substring(start, end)}
      </mark>
    );
    lastEnd = end;
  });

  if (lastEnd < text.length) {
    elements.push(text.substring(lastEnd));
  }

  return <span className={className}>{elements}</span>;
};

// Streamlined dropdown menu for account actions
interface AccountActionDropdownProps {
  acc: UserAccount;
  buttonLabel?: string;
  buttonClassName?: string;
  align?: 'left' | 'right';
  onOpenStudentDetails: (acc: UserAccount) => void;
  onOpenResetModal: (acc: UserAccount) => void;
  onOpenEmailModal: (acc: UserAccount) => void;
  onOpenAuditHistory?: (acc: UserAccount) => void;
  onEdit: (acc: UserAccount) => void;
  onTriggerLostStreak: (acc: UserAccount) => void;
  onDelete: (acc: UserAccount) => void;
  onRestore?: (acc: UserAccount) => void;
  onPermanentDelete?: (acc: UserAccount) => void;
}

const AccountActionDropdown: React.FC<AccountActionDropdownProps> = ({
  acc,
  buttonLabel = 'Thao tác',
  buttonClassName,
  align = 'right',
  onOpenStudentDetails,
  onOpenResetModal,
  onOpenEmailModal,
  onOpenAuditHistory,
  onEdit,
  onTriggerLostStreak,
  onDelete,
  onRestore,
  onPermanentDelete,
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen]);

  return (
    <div className="relative inline-block text-left shrink-0" ref={dropdownRef}>
      <button
        type="button"
        onClick={(e) => {
          e.stopPropagation();
          audioService.playClickSound();
          setIsOpen(!isOpen);
        }}
        className={buttonClassName || "px-2.5 py-1.5 rounded-xl bg-indigo-50 hover:bg-indigo-100 text-indigo-700 border border-indigo-200/80 font-extrabold text-xs inline-flex items-center gap-1.5 whitespace-nowrap shrink-0 transition cursor-pointer shadow-2xs active:scale-95"}
        title="Thao tác quản lý tài khoản"
      >
        <MoreVertical size={14} className="shrink-0" />
        <span className="whitespace-nowrap">{buttonLabel}</span>
        <ChevronDown size={12} className={`transition-transform duration-200 shrink-0 ${isOpen ? 'rotate-180' : ''}`} />
      </button>

      {isOpen && (
        <div className={`absolute ${align === 'left' ? 'left-0 origin-top-left' : 'right-0 origin-top-right'} mt-1.5 w-60 max-h-80 overflow-y-auto custom-scrollbar bg-white rounded-2xl border border-slate-200 shadow-2xl z-[70] p-1.5 space-y-0.5 animate-fadeIn text-left text-xs font-bold text-slate-700`}>
          {acc.isDeleted ? (
            <>
              {onRestore && (
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    setIsOpen(false);
                    onRestore(acc);
                  }}
                  className="w-full px-2.5 py-2 hover:bg-emerald-50 text-emerald-700 rounded-xl flex items-center gap-2 whitespace-nowrap transition cursor-pointer"
                >
                  <RotateCcw size={14} className="text-emerald-600 shrink-0" />
                  <span>Khôi phục tài khoản</span>
                </button>
              )}
              {onPermanentDelete && (
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    setIsOpen(false);
                    onPermanentDelete(acc);
                  }}
                  className="w-full px-2.5 py-2 hover:bg-rose-50 text-rose-700 rounded-xl flex items-center gap-2 whitespace-nowrap transition cursor-pointer"
                >
                  <Trash2 size={14} className="text-rose-600 shrink-0" />
                  <span>Xóa vĩnh viễn</span>
                </button>
              )}
            </>
          ) : (
            <>
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setIsOpen(false);
                  onOpenStudentDetails(acc);
                }}
                className="w-full px-2.5 py-2 hover:bg-indigo-50 text-indigo-700 rounded-xl flex items-center gap-2 whitespace-nowrap transition cursor-pointer"
              >
                <Activity size={14} className="text-indigo-600 shrink-0" />
                <span>Xem bài học gần đây</span>
              </button>

              {onOpenAuditHistory && (
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    setIsOpen(false);
                    onOpenAuditHistory(acc);
                  }}
                  className="w-full px-2.5 py-2 hover:bg-purple-50 text-purple-800 rounded-xl flex items-center gap-2 whitespace-nowrap transition cursor-pointer"
                >
                  <History size={14} className="text-purple-600 shrink-0" />
                  <span>Audit History (Lịch sử)</span>
                </button>
              )}

              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setIsOpen(false);
                  onOpenResetModal(acc);
                }}
                className="w-full px-2.5 py-2 hover:bg-slate-100 text-slate-700 rounded-xl flex items-center gap-2 whitespace-nowrap transition cursor-pointer"
              >
                <RotateCcw size={14} className="text-slate-500 shrink-0" />
                <span>Reset chỉ số (Lvl, Star, Streak)</span>
              </button>

              {acc.role === 'kid' && (
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    setIsOpen(false);
                    onOpenEmailModal(acc);
                  }}
                  className="w-full px-2.5 py-2 hover:bg-sky-50 text-sky-700 rounded-xl flex items-center gap-2 whitespace-nowrap transition cursor-pointer"
                >
                  <Mail size={14} className="text-sky-600 shrink-0" />
                  <span>Gửi email cho phụ huynh</span>
                </button>
              )}

              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setIsOpen(false);
                  onEdit(acc);
                }}
                className="w-full px-2.5 py-2 hover:bg-amber-50 text-amber-800 rounded-xl flex items-center gap-2 whitespace-nowrap transition cursor-pointer"
              >
                <Edit size={14} className="text-amber-600 shrink-0" />
                <span>Sửa thông tin tài khoản</span>
              </button>

              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setIsOpen(false);
                  onTriggerLostStreak(acc);
                }}
                className="w-full px-2.5 py-2 hover:bg-rose-50 text-rose-700 rounded-xl flex items-center gap-2 whitespace-nowrap transition cursor-pointer"
              >
                <Flame size={14} className="text-rose-500 fill-rose-400 shrink-0" />
                <span>Báo mất chuỗi (0 Ngày)</span>
              </button>

              <div className="border-t border-slate-100 my-1" />

              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setIsOpen(false);
                  onDelete(acc);
                }}
                className="w-full px-2.5 py-2 hover:bg-red-50 text-red-600 font-extrabold rounded-xl flex items-center gap-2 transition cursor-pointer"
              >
                <Trash2 size={14} className="text-red-500 shrink-0" />
                <span>Xóa tài khoản (Thùng rác)</span>
              </button>
            </>
          )}
        </div>
      )}
    </div>
  );
};

