  const performAccountRevert = (
    currentAcc: UserAccount,
    oldValue?: string,
    newValue?: string,
    previousAccount?: any
  ): UserAccount => {
    if (previousAccount && typeof previousAccount === 'object' && previousAccount.id) {
      return { ...previousAccount };
    }

    let restored = { ...currentAcc };

    // 1. Try parsing JSON if oldValue is a JSON string
    if (oldValue && oldValue.trim().startsWith('{') && oldValue.trim().endsWith('}')) {
      try {
        const parsed = JSON.parse(oldValue);
        if (parsed && typeof parsed === 'object') {
          return { ...restored, ...parsed };
        }
      } catch (e) {
        // ignore
      }
    }

    if (!oldValue) return restored;

    const oldLower = oldValue.toLowerCase();

    // 2. VIP status & expiry revert
    if (oldLower.includes('miễn phí') || oldLower.includes('hết hạn') || oldLower.includes('chưa có vip')) {
      restored.isVip = false;
      restored.vipExpiryDate = undefined;
    } else if (oldLower.includes('vip')) {
      restored.isVip = true;
      const dateMatch = oldValue.match(/\d{1,2}\/\d{1,2}\/\d{4}/);
      if (dateMatch) {
        restored.vipExpiryDate = dateMatch[0];
      }
    }

    // 3. Stars revert
    const starsMatch = oldValue.match(/(\d+)\s*(sao|star)/i);
    if (starsMatch) {
      restored.stars = parseInt(starsMatch[1], 10) || 0;
    }

    // 4. XP revert
    const xpMatch = oldValue.match(/(\d+)\s*xp/i);
    if (xpMatch) {
      restored.xp = parseInt(xpMatch[1], 10) || 0;
    }

    // 5. Level revert
    const levelMatch = oldValue.match(/level\s*(\d+)/i) || oldValue.match(/cấp\s*(\d+)/i) || oldValue.match(/lv\s*(\d+)/i);
    if (levelMatch) {
      restored.level = parseInt(levelMatch[1], 10) || 1;
    }

    // 6. Streak revert
    const streakMatch = oldValue.match(/chuỗi\s*(\d+)/i) || oldValue.match(/streak\s*(\d+)/i);
    if (streakMatch) {
      restored.streak = parseInt(streakMatch[1], 10) || 0;
    }

    // 7. Delete / Trash revert
    if (oldLower.includes('thùng rác') || oldLower.includes('đã xóa') || oldLower.includes('xóa')) {
      restored.isDeleted = false;
    }

    // 8. Locked status revert
    if (oldLower.includes('chưa bị khóa') || oldLower.includes('hoạt động') || oldLower.includes('mở khóa')) {
      restored.isLocked = false;
      restored.status = 'active';
    } else if (oldLower.includes('bị khóa') || oldLower.includes('khóa')) {
      restored.isLocked = true;
      restored.status = 'locked';
    }

    // 9. Role revert
    if (oldLower.includes('admin')) restored.role = 'admin';
    else if (oldLower.includes('phụ huynh') || oldLower.includes('parent')) restored.role = 'parent';
    else if (oldLower.includes('học sinh') || oldLower.includes('kid') || oldLower.includes('student')) restored.role = 'kid';

    return restored;
  };

