                    accountSortField === 'createdAt' && accountSortOrder === 'desc'
                      ? 'bg-amber-500 text-slate-950 border-amber-500 shadow-2xs font-black'
                      : 'bg-slate-50 hover:bg-amber-50 text-amber-900 border-slate-200 hover:border-amber-200'
